/**
 * amfa-442 W3-1 (D1): logRequest logs the request summary and nothing else
 * from the API Gateway event. The event carries the bearer token, cookies and
 * the request body; none of them may reach CloudWatch.
 * Run: node --test test/*.test.mjs (from the admin-auth dir; no AWS SDK needed).
 */
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { logRequest } from '../log-utils.cjs';

const EVENT = {
  version: '2.0',
  routeKey: 'PUT /tenants/{id}',
  rawPath: '/tenants/acme01',
  headers: { authorization: 'Bearer SECRET-DO-NOT-LEAK', cookie: 'session=SECRET-DO-NOT-LEAK', 'x-tenant-id': 'acme01' },
  body: JSON.stringify({ data: { pass: 'SECRET-DO-NOT-LEAK' } }),
  pathParameters: { id: 'acme01' },
  requestContext: {
    requestId: 'req-1',
    routeKey: 'PUT /tenants/{id}',
    http: { method: 'PUT', path: '/tenants/acme01', sourceIp: '203.0.113.9' },
    authorizer: { jwt: { claims: { 'cognito:groups': '[SA]', sub: 'SECRET-DO-NOT-LEAK' } } },
  },
};

const capture = () => { const calls = []; return { calls, logger: { info: (m, e) => calls.push([m, e]) } }; };

describe('logRequest', () => {
  test('logs exactly method/path/requestId/sourceIp and no authorization, body or headers', () => {
    const { calls, logger } = capture();
    logRequest(logger, EVENT);
    assert.equal(calls.length, 1);
    const [message, entry] = calls[0];
    assert.equal(message, 'request');
    assert.deepEqual(entry, { method: 'PUT', path: '/tenants/acme01', requestId: 'req-1', sourceIp: '203.0.113.9' });
    assert.ok(!JSON.stringify(calls).includes('SECRET-DO-NOT-LEAK'));
  });

  test('adds the verified tenantId from the caller or from the Lambda authorizer context', () => {
    const { calls, logger } = capture();
    logRequest(logger, EVENT, 'acme01');
    assert.equal(calls[0][1].tenantId, 'acme01');
    const ctx = { ...EVENT.requestContext, authorizer: { lambda: { tenantId: 'acme02' } } };
    logRequest(logger, { ...EVENT, requestContext: ctx });
    assert.equal(calls[1][1].tenantId, 'acme02');
  });

  test('tolerates REST v1 and empty events', () => {
    const { calls, logger } = capture();
    logRequest(logger, { path: '/x', requestContext: { httpMethod: 'GET', identity: { sourceIp: '198.51.100.1' } } });
    assert.deepEqual(calls[0][1], { method: 'GET', path: '/x', sourceIp: '198.51.100.1' });
    logRequest(logger, undefined);
    assert.deepEqual(calls[1][1], {});
  });
});
